function solve(nums) {
  if (!nums.length) return 0;
  const s = [...new Set(nums)].sort((a, b) => a - b);
  let best = 1, cur = 1;
  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1] + 1) { cur++; best = Math.max(best, cur); }
    else cur = 1;
  }
  return best;
}

function solve(nums) {
  const seen = new Set(nums);
  let best = 0;
  for (const n of seen) {
    if (!seen.has(n - 1)) {
      let cur = 1, x = n;
      while (seen.has(x + 1)) { x++; cur++; }
      best = Math.max(best, cur);
    }
  }
  return best;
}

